const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim();
const n = parseInt(input, 10);

const dp = new Array(n + 1).fill(Infinity);
dp[0] = 0;

for (let i = 1; i <= n; i++) {
    let x = i;
    let best = Infinity;

    while (x > 0) {
        const digit = x % 10;
        x = Math.floor(x / 10);

        if (digit > 0) {
            const candidate = dp[i - digit] + 1;
            if (candidate < best) {
                best = candidate;
            }
        }
    }

    dp[i] = best;
}

console.log(dp[n]);
